(function (global) {
    "use strict";
    let serial = 0;
    const chapterCounts = {};
    function q(chapterId, difficulty, en, hi, choices, answer, why, whyHi) {
        serial += 1;
        chapterCounts[chapterId] = (chapterCounts[chapterId] || 0) + 1;
        const offset = (serial - 1) % 4;
        const questionId = "M2-" + String(serial).padStart(3, "0");
        const chapter = global.OLEVEL_CATALOG[1].chapters.find(function (entry) { return entry.id === chapterId; });
        const topicIndex = (chapterCounts[chapterId] - 1) % chapter.topics.length;
        const options = choices.map(function (choice, index) { return { id: questionId + "-O" + (index + 1), en: choice[0], hi: choice[1] }; });
        const orderedChoices = options.slice(offset).concat(options.slice(0, offset));
        return {
            id: questionId, moduleId: "M2-R5.1", chapterId: chapterId,
            topicId: chapterId + "-topic-" + (topicIndex + 1), topic: chapter.topics[topicIndex],
            difficulty: difficulty, questionEnglish: en, questionHindi: hi,
            options: orderedChoices, correctOptionId: options[answer].id,
            explanationEnglish: why, explanationHindi: whyHi,
            sourceType: "Original Practice", source: { name: "ZeroKB original practice", year: null }
        };
    }
    global.OLEVEL_BANKS = global.OLEVEL_BANKS || {};
    global.OLEVEL_BANKS.m2 = [
        q("web-design-intro", "Moderate", "A page is readable on a phone and a desktop without requiring horizontal scrolling. Which design approach most directly supports this?", "पेज फोन और डेस्कटॉप दोनों पर क्षैतिज स्क्रॉल के बिना पढ़ा जा सकता है। कौन-सा डिज़ाइन तरीका सीधे इसका समर्थन करता है?", [["Responsive layout using flexible sizing and media queries", "लचीले आकार और media queries वाला responsive layout"], ["Fixed-width canvas wider than a phone", "फोन से चौड़ा fixed-width canvas"], ["Images of all page text", "पेज के पूरे टेक्स्ट की इमेज"], ["A separate unlinked page for each screen width", "हर स्क्रीन चौड़ाई के लिए अलग-अलग असंबद्ध पेज"]], 0, "Responsive design adapts layout to viewport size using flexible rules rather than a single rigid width.", "Responsive डिज़ाइन एक कठोर चौड़ाई के बजाय लचीले नियमों से viewport के अनुसार लेआउट बदलता है।"),
        q("web-design-intro", "Hard", "A form visually labels its fields, but assistive technology announces only \"edit text\". Which improvement best addresses the semantic gap?", "फॉर्म में फ़ील्ड के लेबल दिखते हैं, लेकिन सहायक तकनीक केवल \"edit text\" बताती है। semantic कमी को कौन-सा सुधार दूर करेगा?", [["Associate each control with a programmatic label", "हर नियंत्रण के साथ प्रोग्रामेटिक label जोड़ें"], ["Increase the label font size only", "केवल label का फ़ॉन्ट बड़ा करें"], ["Use color to distinguish fields", "फ़ील्ड अलग करने के लिए रंग उपयोग करें"], ["Replace labels with placeholder text only", "लेबल हटाकर केवल placeholder रखें"]], 0, "Programmatic labels expose each control's purpose to assistive technology and improve form accessibility.", "प्रोग्रामेटिक labels सहायक तकनीक को नियंत्रण का उद्देश्य बताते हैं और फॉर्म की सुगम्यता बढ़ाते हैं।"),

        q("editors", "Moderate", "A developer wants to find every occurrence of a class name across a multi-file site and change it consistently. Which editor capability is most useful?", "डेवलपर को कई फाइलों वाली साइट में class name के सभी उपयोग खोजकर समान रूप से बदलने हैं। कौन-सी editor क्षमता सबसे उपयोगी है?", [["Workspace-wide search and replace", "पूरे workspace में खोज और प्रतिस्थापन"], ["Changing the editor theme", "editor थीम बदलना"], ["Zooming the preview", "preview zoom करना"], ["Renaming the operating-system user", "ऑपरेटिंग सिस्टम उपयोगकर्ता का नाम बदलना"]], 0, "Workspace search finds occurrences across files so the change can be reviewed and applied consistently.", "Workspace search अनेक फाइलों में occurrences ढूँढता है ताकि बदलाव की समीक्षा कर उसे समान रूप से लागू किया जा सके।"),
        q("editors", "Hard", "A web project must be edited by several people, and changes should be traceable and reversible. Which workflow capability best supports that requirement?", "वेब परियोजना कई लोगों द्वारा संपादित होगी और बदलावों को ट्रैक तथा वापस किया जा सके। कौन-सी workflow क्षमता इसका सबसे अच्छा समर्थन करती है?", [["Version control with meaningful commits", "सार्थक commits वाला version control"], ["A single shared file repeatedly overwritten", "बार-बार overwrite की जाने वाली एक साझा फाइल"], ["Screenshot history only", "केवल स्क्रीनशॉट इतिहास"], ["Different filenames without change records", "बदलाव रिकॉर्ड के बिना अलग-अलग फाइल नाम"]], 0, "Version control records change history and supports review, collaboration and rollback.", "Version control बदलाव इतिहास दर्ज करता है और समीक्षा, सहयोग तथा rollback में मदद करता है।"),

        q("html", "Moderate", "A page has a main heading, navigation, primary content and a footer. Which markup choice improves document structure for both browsers and assistive tools?", "पेज में मुख्य शीर्षक, नेविगेशन, मुख्य सामग्री और फुटर हैं। ब्राउज़र और सहायक उपकरणों के लिए कौन-सा markup संरचना सुधारता है?", [["Use semantic elements such as main, nav and footer", "main, nav और footer जैसे semantic elements उपयोग करें"], ["Wrap everything in anonymous div elements", "सब कुछ बिना अर्थ वाले div में रखें"], ["Represent headings with bold paragraphs only", "शीर्षकों को केवल bold paragraphs से दिखाएँ"], ["Use table cells to create page layout", "पेज लेआउट के लिए table cells उपयोग करें"]], 0, "Semantic HTML communicates the role of page regions instead of relying only on visual styling.", "Semantic HTML केवल दृश्य शैली पर निर्भर रहने के बजाय पेज क्षेत्रों की भूमिका बताता है।"),
        q("html", "Hard", "A site uses an external stylesheet and a script that queries an element by ID. Which placement most reliably lets the script find the parsed element without blocking page parsing?", "साइट बाहरी stylesheet और ID से element खोजने वाली script उपयोग करती है। पेज parsing रोके बिना script को parsed element उपलब्ध कराने के लिए कौन-सा तरीका अधिक विश्वसनीय है?", [["Load the external script with defer", "बाहरी script को defer के साथ लोड करें"], ["Place a blocking script in the head without defer", "head में defer के बिना blocking script रखें"], ["Remove the element's ID", "element की ID हटा दें"], ["Load the script as an image", "script को image की तरह लोड करें"]], 0, "A deferred external script runs after HTML parsing and before DOMContentLoaded, so parsed elements are available.", "defer वाली बाहरी script HTML parsing के बाद और DOMContentLoaded से पहले चलती है, इसलिए parsed elements उपलब्ध होते हैं।"),

        q("css", "Easy", "Two CSS rules target the same paragraph with equal specificity. The later rule sets the text color. Which color is normally applied?", "दो CSS नियम समान specificity के साथ एक ही paragraph को target करते हैं। बाद वाला नियम text color सेट करता है। सामान्यतः कौन-सा रंग लागू होगा?", [["The color from the later rule in source order", "source क्रम में बाद वाले नियम का रंग"], ["The color from the first rule always", "हमेशा पहले नियम का रंग"], ["A random color chosen by the browser", "ब्राउज़र द्वारा चुना गया कोई भी रंग"], ["No color because equal specificity cancels both", "समान specificity के कारण कोई रंग नहीं"]], 0, "When origin and importance are equal, specificity is tied, so source order breaks the tie.", "जब origin और importance समान हों, specificity बराबर रहती है और source order निर्णय करता है।"),
        q("css", "Hard", "A child element's width is set to 100% and also has horizontal padding. Without box-sizing:border-box, why might it overflow its parent?", "एक child element की width 100% है और उसमें horizontal padding भी है। box-sizing:border-box के बिना वह parent से बाहर क्यों जा सकता है?", [["The content width is 100%, then padding is added outside that width", "content की चौड़ाई 100% होती है और padding उस चौड़ाई के बाहर जुड़ती है"], ["Padding is always subtracted from the containing width", "padding हमेशा container की चौड़ाई से घटती है"], ["CSS ignores all percentage widths", "CSS सभी प्रतिशत चौड़ाइयों को अनदेखा करता है"], ["The browser adds the margin twice", "ब्राउज़र margin को दो बार जोड़ता है"]], 0, "With the content-box model, declared width applies to content and padding is added to the rendered outer width.", "content-box मॉडल में घोषित width content पर लागू होती है और padding प्रदर्शित बाहरी चौड़ाई में जुड़ती है।"),

        q("css-frameworks", "Moderate", "A responsive framework grid changes from two columns to one on narrow screens. What framework feature normally controls this transition?", "एक responsive framework grid संकरी स्क्रीन पर दो कॉलम से एक कॉलम हो जाता है। इस बदलाव को सामान्यतः कौन-सी framework सुविधा नियंत्रित करती है?", [["Breakpoint-based grid classes", "breakpoint आधारित grid classes"], ["HTML comments", "HTML comments"], ["Image alt text", "image alt text"], ["A DNS record", "DNS record"]], 0, "Responsive grid classes apply different column rules at configured viewport breakpoints.", "Responsive grid classes निर्धारित viewport breakpoints पर अलग column नियम लागू करती हैं।"),
        q("css-frameworks", "Hard", "A project uses a CSS framework but needs a distinct color palette and spacing system. What is the safer maintenance approach?", "परियोजना CSS framework उपयोग करती है, लेकिन उसे अलग color palette और spacing system चाहिए। रखरखाव का सुरक्षित तरीका क्या है?", [["Override documented design tokens or add scoped custom styles after the framework", "दस्तावेज़ित design tokens बदलें या framework के बाद सीमित custom styles जोड़ें"], ["Edit minified framework files directly", "minified framework फाइलें सीधे संपादित करें"], ["Duplicate every framework rule into the HTML", "हर framework नियम HTML में दोहराएँ"], ["Remove semantic class names from the markup", "markup से semantic class names हटाएँ"]], 0, "Documented tokens and scoped overrides are easier to maintain than editing bundled vendor code.", "दस्तावेज़ित tokens और सीमित overrides, vendor code बदलने की तुलना में आसान रखरखाव देते हैं।"),

        q("javascript", "Moderate", "A button should update a message when clicked. Which browser-side mechanism is appropriate for responding to that user action?", "क्लिक होने पर बटन को संदेश अपडेट करना है। उपयोगकर्ता की इस क्रिया पर प्रतिक्रिया के लिए कौन-सा browser-side तंत्र उपयुक्त है?", [["Register a click event listener", "click event listener पंजीकृत करें"], ["Change the DNS resolver", "DNS resolver बदलें"], ["Add a database index", "database index जोड़ें"], ["Set an HTTP response header from CSS", "CSS से HTTP response header सेट करें"]], 0, "A click listener runs a JavaScript handler when the browser dispatches a click event on the button.", "बटन पर browser click event भेजता है तो click listener JavaScript handler चलाता है।"),
        q("javascript", "Hard", "A script compares the string \"5\" with the number 5 using ===. What is the result, and why?", "एक script string \"5\" की number 5 से === द्वारा तुलना करती है। परिणाम क्या होगा और क्यों?", [["False, because strict equality does not coerce different types", "False, क्योंकि strict equality अलग-अलग types को coerce नहीं करती"], ["True, because every comparison converts values to strings", "True, क्योंकि हर तुलना मानों को string बनाती है"], ["True, because === ignores operand types", "True, क्योंकि === operand types अनदेखा करता है"], ["A syntax error, because strings cannot be compared", "Syntax error, क्योंकि strings की तुलना नहीं हो सकती"]], 0, "Strict equality checks both value and type, so a string and a number are not strictly equal.", "Strict equality मान और type दोनों जाँचती है, इसलिए string और number strict रूप से बराबर नहीं हैं।"),

        q("image-editing", "Moderate", "An editor needs to remove a background while retaining the ability to adjust the selection later. Which approach best preserves editability?", "संपादक को पृष्ठभूमि हटानी है, लेकिन बाद में चयन बदलने की क्षमता रखनी है। कौन-सा तरीका संपादन-क्षमता बेहतर बचाता है?", [["Use a layer mask on a separate image layer", "अलग image layer पर layer mask उपयोग करें"], ["Erase pixels permanently from the only layer", "एकमात्र layer से pixels स्थायी रूप से मिटाएँ"], ["Flatten the image before selecting", "चयन से पहले image flatten करें"], ["Save only a JPEG copy", "केवल JPEG प्रति सहेजें"]], 0, "A mask hides pixels non-destructively, allowing the mask edge to be refined later.", "Mask pixels को non-destructive तरीके से छिपाता है, जिससे किनारे बाद में सुधारे जा सकते हैं।"),
        q("image-editing", "Hard", "A logo must remain crisp when enlarged for a banner and reduced for a business card. Which source format is generally the better choice?", "बैनर के लिए बड़ा और business card के लिए छोटा करने पर लोगो स्पष्ट रहना चाहिए। सामान्यतः कौन-सा स्रोत प्रारूप बेहतर है?", [["Vector artwork", "Vector artwork"], ["A low-resolution raster thumbnail", "कम resolution वाली raster thumbnail"], ["A compressed screenshot", "संपीड़ित screenshot"], ["A palette-limited GIF photograph", "सीमित palette वाली GIF तस्वीर"]], 0, "Vector paths scale by geometry and remain sharp at different sizes; raster pixels can become visibly enlarged.", "Vector paths ज्यामिति से आकार बदलते हैं और अलग आकारों पर स्पष्ट रहते हैं; raster pixels बड़े करने पर दिखने लगते हैं।"),

        q("web-publishing", "Moderate", "A newly published site works at its server IP address but not at its domain name. Which configuration should be checked first?", "नई प्रकाशित साइट server IP पर चलती है, लेकिन domain name पर नहीं। पहले कौन-सा configuration जाँचना चाहिए?", [["The domain's DNS records and delegation", "डोमेन के DNS records और delegation"], ["The image editor's color profile", "image editor का color profile"], ["The visitor's spreadsheet formulas", "विज़िटर के spreadsheet सूत्र"], ["The HTML heading level", "HTML heading level"]], 0, "DNS records and delegation connect a domain name to the hosting service.", "DNS records और delegation डोमेन नाम को hosting सेवा से जोड़ते हैं।"),
        q("web-publishing", "Hard", "A site is reachable over HTTPS, but mixed-content warnings appear because a page loads an image over HTTP. What is the appropriate correction?", "साइट HTTPS पर खुलती है, पर HTTP से image लोड होने के कारण mixed-content चेतावनी आती है। उचित सुधार क्या है?", [["Serve the image over HTTPS and update the resource URL", "image को HTTPS से serve करके resource URL अपडेट करें"], ["Disable certificate checks in the browser", "ब्राउज़र में certificate checks बंद करें"], ["Rename the image extension", "image extension का नाम बदलें"], ["Move the image below the footer", "image को footer के नीचे ले जाएँ"]], 0, "An HTTPS page should load its resources securely; converting the image URL to HTTPS removes this mixed-content request.", "HTTPS पेज को संसाधन सुरक्षित रूप से लोड करने चाहिए; image URL को HTTPS करने से mixed-content request हटती है।"),
        q("web-design-intro", "Moderate", "A page must reflow for narrow screens while keeping its navigation and reading order understandable. Which layout decision best supports that goal?", "संकरी स्क्रीन पर पेज को reflow होना है और navigation तथा पढ़ने का क्रम समझने योग्य रहना चाहिए। कौन-सा layout निर्णय बेहतर है?", [["Use a fluid content column and a breakpoint that stacks secondary regions", "Fluid content column और breakpoint पर secondary regions को stack करें"], ["Set a fixed minimum width larger than the viewport", "Viewport से बड़ा fixed minimum width रखें"], ["Scale the entire page as a single image", "पूरे पेज को एक image की तरह scale करें"], ["Position every element with unrelated absolute coordinates", "हर element को अलग absolute coordinates पर रखें"]], 0, "Fluid sizing and an intentional breakpoint preserve content flow at small widths.", "Fluid sizing और सोचा-समझा breakpoint छोटी चौड़ाई पर content flow बनाए रखते हैं।"),
        q("editors", "Hard", "A page fails only after a particular user interaction. Which editor tool can pause execution at a chosen JavaScript line so variables can be inspected?", "एक खास user interaction के बाद ही पेज विफल होता है। कौन-सा editor tool चुनी हुई JavaScript line पर execution रोककर variables देखने देता है?", [["A debugger breakpoint", "Debugger breakpoint"], ["A formatter", "Formatter"], ["A color picker", "Color picker"], ["A project file explorer", "Project file explorer"]], 0, "A breakpoint pauses code so the current call stack and variable values can be examined.", "Breakpoint code रोकता है ताकि वर्तमान call stack और variable values देखे जा सकें।"),
        q("html", "Easy", "A label should focus a text input when the user activates the label text. Which markup relationship provides that behavior?", "Label text सक्रिय करने पर संबंधित text input focus होना चाहिए। कौन-सा markup संबंध यह व्यवहार देता है?", [["Set the label's for value to the input's matching id", "Label का for, input की matching id पर रखें"], ["Give the label and input the same name only", "केवल label और input का name समान रखें"], ["Place the input in a table footer", "Input को table footer में रखें"], ["Use a title attribute on the form", "Form पर title attribute लगाएँ"]], 0, "A label's for attribute associates it with the form control whose id matches.", "Label का for attribute उस form control से जुड़ता है जिसकी id समान हो।"),
        q("css", "Hard", "A page's link has a class rule and a later element rule with equal specificity, but the class rule is marked !important. Which declaration wins?", "पेज के link पर class rule और बाद में आया element rule समान specificity रखते हैं, लेकिन class rule !important है। कौन-सा declaration लागू होगा?", [["The important declaration, unless another important declaration wins by cascade rules", "महत्वपूर्ण declaration, जब तक cascade नियमों में दूसरा important declaration न जीते"], ["Always the later ordinary element rule", "हमेशा बाद वाला सामान्य element rule"], ["Neither rule because specificity ties", "कोई नहीं क्योंकि specificity बराबर है"], ["The browser default color", "ब्राउज़र का default रंग"]], 0, "!important declarations are prioritized over ordinary declarations before specificity and source order are compared.", "!important declarations को specificity और source order की तुलना से पहले सामान्य declarations पर प्राथमिकता मिलती है।"),
        q("css-frameworks", "Moderate", "A component looks correct in one framework version but changes after an upgrade because undocumented internal classes were overridden. What reduces this coupling?", "एक framework version में component सही दिखता है, लेकिन undocumented internal classes override होने से upgrade के बाद बदल जाता है। इस coupling को क्या घटाता है?", [["Use documented customization variables and stable public classes", "Documented customization variables और स्थिर public classes उपयोग करें"], ["Override generated class names copied from browser inspection", "Browser inspection से copied generated class names override करें"], ["Modify framework output after every build", "हर build के बाद framework output बदलें"], ["Duplicate the whole framework stylesheet", "पूरी framework stylesheet duplicate करें"]], 0, "Public APIs and documented tokens are more stable than internal implementation selectors.", "Public APIs और documented tokens, internal implementation selectors से अधिक स्थिर होते हैं।"),
        q("javascript", "Easy", "A script needs to update text entered into the page without interpreting it as markup. Which DOM property is the safer fit?", "Script को पेज में entered text दिखाना है लेकिन markup की तरह interpret नहीं करना। कौन-सी DOM property सुरक्षित है?", [["textContent", "textContent"], ["innerHTML with an untrusted string", "Untrusted string के साथ innerHTML"], ["outerHTML concatenation", "outerHTML concatenation"], ["document.write after load", "Load के बाद document.write"]], 0, "textContent inserts text as text rather than parsing it as HTML markup.", "textContent सामग्री को HTML markup की तरह parse करने के बजाय text के रूप में डालता है।"),
        q("image-editing", "Hard", "A photograph will be printed at a fixed physical size. Which pair of properties is most relevant to judging whether it has enough detail for that print?", "एक photograph निश्चित physical size पर print होगी। Print के लिए पर्याप्त detail है या नहीं, यह जाँचने में कौन-सी दो properties महत्वपूर्ण हैं?", [["Pixel dimensions together with intended print resolution", "Pixel dimensions और इच्छित print resolution"], ["File extension and layer count only", "केवल file extension और layer count"], ["Screen brightness and browser zoom", "Screen brightness और browser zoom"], ["Number of colors in the editor toolbar", "Editor toolbar में रंगों की संख्या"]], 0, "Available pixels over the intended physical dimensions determine effective print resolution.", "उपलब्ध pixels और इच्छित physical dimensions से प्रभावी print resolution तय होती है।"),
        q("web-publishing", "Moderate", "A browser keeps showing an older stylesheet after the server file was updated. Which common publishing issue should be checked first?", "Server पर file update होने के बाद भी browser पुरानी stylesheet दिखाता है। पहले कौन-सी सामान्य publishing समस्या जाँचें?", [["Browser or intermediary cache serving a stale resource", "Browser या intermediary cache पुराना resource दे रहा है"], ["The HTML document has too many headings", "HTML document में बहुत headings हैं"], ["The image uses a vector format", "Image vector format में है"], ["The CSS selector uses a class", "CSS selector class का उपयोग करता है"]], 0, "A stale cached response can persist after deployment; verify cache headers or use an appropriate versioned asset URL.", "Deployment के बाद पुराना cached response रह सकता है; cache headers या उपयुक्त versioned asset URL जाँचें।"),

        q("web-design-intro", "Moderate", "When a browser requests a page, which role does the web server normally perform?", "जब browser किसी पेज का अनुरोध करता है, तो web server सामान्यतः कौन-सी भूमिका निभाता है?", [["It receives the request and returns the requested resource or response", "यह अनुरोध प्राप्त करके माँगा गया resource या response लौटाता है"], ["It permanently stores the visitor's browser history", "यह आगंतुक का browser history स्थायी रूप से रखता है"], ["It converts every page into an image", "यह हर पेज को image में बदलता है"], ["It chooses the monitor resolution", "यह monitor का resolution चुनता है"]], 0, "A browser acts as a client and communicates with a server that processes requests and sends responses.", "Browser client की तरह काम करता है और server से संवाद करता है, जो अनुरोध संसाधित करके response भेजता है।", "Expected Practice"),
        q("web-design-intro", "Moderate", "A site map is being planned before any page is coded. What is its main design benefit?", "किसी पेज की coding से पहले site map बनाया जा रहा है। इसका मुख्य design लाभ क्या है?", [["It clarifies page hierarchy and navigation relationships", "यह पेजों का पदानुक्रम और navigation संबंध स्पष्ट करता है"], ["It compresses image files automatically", "यह image files को अपने आप compress करता है"], ["It assigns an IP address to the site", "यह site को IP address देता है"], ["It replaces the need to test links", "यह links जाँचने की आवश्यकता समाप्त करता है"]], 0, "A site map makes the information structure and paths between pages easier to plan and review.", "Site map से जानकारी की संरचना और पेजों के बीच रास्तों की योजना तथा समीक्षा आसान होती है।", "Expected Practice"),
        q("web-design-intro", "Moderate", "A long form is difficult to complete because unrelated questions appear in one block. Which planning change best improves usability?", "असंबंधित प्रश्न एक ही block में होने के कारण लंबा form भरना कठिन है। कौन-सा planning बदलाव usability बेहतर करेगा?", [["Group related fields under clear section headings", "संबंधित fields को स्पष्ट section headings के अंतर्गत समूहित करें"], ["Hide all labels until submission", "Submission तक सभी labels छिपाएँ"], ["Make every field mandatory regardless of purpose", "उद्देश्य की परवाह किए बिना हर field अनिवार्य करें"], ["Place each field at a random position", "हर field को अनियमित स्थान पर रखें"]], 0, "Logical grouping reduces cognitive load and helps users understand the form's structure.", "तार्किक grouping मानसिक बोझ घटाती है और उपयोगकर्ताओं को form की संरचना समझने में मदद करती है।", "Expected Practice"),
        q("web-design-intro", "Moderate", "A design mock-up contains important instructions only as pale text on a colored background. What should be checked before implementation?", "Design mock-up में महत्वपूर्ण निर्देश केवल रंगीन background पर हल्के text में हैं। लागू करने से पहले क्या जाँचना चाहिए?", [["Text/background contrast and legibility", "Text और background का contrast तथा पठनीयता"], ["The server's disk partition format", "Server का disk partition format"], ["Whether the URL contains a query string", "URL में query string है या नहीं"], ["The site's file transfer protocol", "Site का file transfer protocol"]], 0, "Sufficient contrast makes text readable for more users and across varied display conditions.", "पर्याप्त contrast अलग-अलग उपयोगकर्ताओं और display स्थितियों में text पढ़ने योग्य बनाता है।", "Expected Practice"),
        q("web-design-intro", "Moderate", "A site's content is organized so visitors can reach any major section from every page. Which design quality does this most directly demonstrate?", "Site की सामग्री इस तरह व्यवस्थित है कि हर पेज से प्रमुख section तक पहुँचा जा सकता है। यह सीधे किस design गुण को दिखाता है?", [["Consistent information architecture and navigation", "सुसंगत information architecture और navigation"], ["High image compression", "अधिक image compression"], ["Server-side scripting", "Server-side scripting"], ["Raster editing", "Raster editing"]], 0, "Consistent navigation helps visitors understand where they are and move through the site's sections.", "सुसंगत navigation आगंतुकों को अपनी स्थिति समझने और site के sections में जाने में मदद करता है।", "Expected Practice"),
        q("web-design-intro", "Hard", "A team is choosing between a single-page layout and several linked pages for a large reference guide. Which consideration most strongly supports splitting it into pages?", "एक टीम बड़ी reference guide के लिए एक single-page layout और कई linked pages में से चुन रही है। इसे अलग पेजों में बाँटने का सबसे मजबूत कारण क्या है?", [["Distinct topics need stable URLs and focused navigation", "अलग विषयों के लिए स्थिर URLs और केंद्रित navigation चाहिए"], ["The site should avoid using headings", "Site को headings से बचना चाहिए"], ["The content must be displayed as one image", "सामग्री एक image के रूप में दिखानी चाहिए"], ["Browsers cannot render long documents", "Browsers लंबे दस्तावेज़ render नहीं कर सकते"]], 0, "Stable, focused pages can make a large information set easier to navigate, reference and share.", "स्थिर और केंद्रित पेज बड़ी जानकारी को navigate, reference और share करना आसान बना सकते हैं।", "Expected Practice"),
        q("web-design-intro", "Hard", "A page must work with keyboard-only users, but a custom menu currently opens only on pointer hover. What design correction addresses the interaction barrier?", "पेज keyboard-only उपयोगकर्ताओं के लिए भी काम करना चाहिए, लेकिन custom menu अभी केवल pointer hover पर खुलता है। कौन-सा design सुधार यह बाधा दूर करता है?", [["Provide keyboard focus and activation behavior for menu controls", "Menu controls के लिए keyboard focus और activation व्यवहार दें"], ["Increase the hover animation duration", "Hover animation की अवधि बढ़ाएँ"], ["Replace the menu text with icons alone", "Menu text को केवल icons से बदलें"], ["Disable browser focus outlines", "Browser के focus outlines बंद करें"]], 0, "Keyboard-operable controls let users reach and activate navigation without a pointer.", "Keyboard से संचालित controls उपयोगकर्ताओं को pointer के बिना navigation तक पहुँचने और सक्रिय करने देते हैं।", "Expected Practice"),
        q("web-design-intro", "Hard", "An analytics report shows many visitors leave a page before finding its primary action. Which investigation is the most useful first step?", "Analytics report दिखाती है कि मुख्य action मिलने से पहले कई आगंतुक पेज छोड़ देते हैं। सबसे उपयोगी पहला कदम कौन-सी जाँच है?", [["Review task flow and action visibility with representative users", "प्रतिनिधि उपयोगकर्ताओं के साथ task flow और action की दृश्यता की समीक्षा करें"], ["Change the site's domain registrar", "Site का domain registrar बदलें"], ["Increase every image's resolution", "हर image का resolution बढ़ाएँ"], ["Remove all page headings", "पेज की सभी headings हटा दें"]], 0, "Observing users attempt the intended task can reveal navigation or hierarchy problems that analytics alone cannot explain.", "उपयोगकर्ताओं को अपेक्षित काम करते देखना navigation या hierarchy की ऐसी समस्याएँ दिखा सकता है जिन्हें analytics अकेले नहीं समझाती।", "Expected Practice"),

        q("editors", "Moderate", "An editor colors matching HTML tags and attributes differently while typing. Which feature is being used?", "एक editor typing के दौरान HTML tags और attributes को अलग-अलग रंगों में दिखाता है। कौन-सी सुविधा उपयोग हो रही है?", [["Syntax highlighting", "Syntax highlighting"], ["Version branching", "Version branching"], ["DNS resolution", "DNS resolution"], ["Image dithering", "Image dithering"]], 0, "Syntax highlighting visually distinguishes language tokens and can make code easier to scan.", "Syntax highlighting भाषा के tokens को दृश्य रूप से अलग करती है और code पढ़ना आसान बना सकती है।", "Expected Practice"),
        q("editors", "Moderate", "An HTML project should be checked for malformed tags before it is uploaded. Which workflow step is most appropriate?", "HTML project upload करने से पहले गलत tags के लिए जाँचना है। कौन-सा workflow चरण सबसे उपयुक्त है?", [["Run an HTML validator and correct reported errors", "HTML validator चलाकर बताई गई त्रुटियाँ सुधारें"], ["Rename the project folder", "Project folder का नाम बदलें"], ["Change the editor's color theme", "Editor की color theme बदलें"], ["Export every file as a screenshot", "हर file को screenshot के रूप में export करें"]], 0, "Validation catches structural markup problems before they reach the published site.", "Validation प्रकाशित site तक पहुँचने से पहले markup की संरचनात्मक समस्याएँ पकड़ती है।", "Expected Practice"),
        q("editors", "Moderate", "A developer needs to see the current page after editing local HTML and CSS without publishing it publicly. Which editor facility is useful?", "डेवलपर को local HTML और CSS बदलने के बाद उसे सार्वजनिक रूप से publish किए बिना पेज देखना है। कौन-सी editor सुविधा उपयोगी है?", [["A local preview or development server", "Local preview या development server"], ["A domain transfer service", "Domain transfer service"], ["A print color separations panel", "Print color separations panel"], ["A spreadsheet pivot table", "Spreadsheet pivot table"]], 0, "A local preview lets the developer inspect changes in a browser before deployment.", "Local preview developer को deployment से पहले browser में बदलाव देखने देता है।", "Expected Practice"),
        q("editors", "Moderate", "A team repeatedly writes the same opening and closing tags. Which editor aid can insert a prepared code pattern quickly?", "एक team बार-बार वही opening और closing tags लिखती है। कौन-सी editor सहायता तैयार code pattern जल्दी डाल सकती है?", [["A snippet or code completion template", "Snippet या code completion template"], ["A DNS cache", "DNS cache"], ["A raster selection tool", "Raster selection tool"], ["A network firewall rule", "Network firewall rule"]], 0, "Snippets and completion templates reduce repetitive typing and can help keep common code patterns consistent.", "Snippets और completion templates दोहराव वाली typing घटाते हैं और सामान्य code patterns सुसंगत रखने में मदद करते हैं।", "Expected Practice"),
        q("editors", "Moderate", "A web project contains HTML, stylesheets, images and scripts. Why should they be organized in a clear folder structure?", "एक web project में HTML, stylesheets, images और scripts हैं। उन्हें स्पष्ट folder structure में व्यवस्थित क्यों करना चाहिए?", [["It makes dependencies and asset paths easier to locate and maintain", "इससे dependencies और asset paths ढूँढना तथा बनाए रखना आसान होता है"], ["It automatically makes all pages secure", "इससे सभी पेज अपने आप सुरक्षित हो जाते हैं"], ["It removes the need for file extensions", "इससे file extensions की आवश्यकता हट जाती है"], ["It converts scripts into stylesheets", "यह scripts को stylesheets में बदल देता है"]], 0, "A predictable structure supports teamwork and reduces mistakes when linking or updating project files.", "पहचानी जा सकने वाली संरचना सहयोग में मदद करती है और project files जोड़ने या बदलने की गलतियाँ घटाती है।", "Expected Practice"),
        q("editors", "Hard", "A minified production script fails, while its readable source version works. Which debugging aid best maps the production code back to its source?", "Minified production script विफल होती है, जबकि readable source version चलती है। कौन-सी debugging सहायता production code को source से जोड़ती है?", [["A source map", "Source map"], ["A CSS reset", "CSS reset"], ["An image alpha channel", "Image alpha channel"], ["A DNS TXT record", "DNS TXT record"]], 0, "Source maps help developer tools associate transformed or minified code with its original source locations.", "Source maps developer tools को transformed या minified code को उसके मूल source स्थानों से जोड़ने में मदद करते हैं।", "Expected Practice"),
        q("editors", "Hard", "An editor extension requests permission to read and modify every file in a project, although it only formats CSS. What is the best review response?", "एक editor extension CSS formatting के लिए है, लेकिन वह project की हर file पढ़ने और बदलने की अनुमति माँगती है। सबसे अच्छा review कदम क्या है?", [["Check its provenance and permission scope, and prefer a narrower trusted tool", "उसका स्रोत और अनुमति-सीमा जाँचें तथा अधिक सीमित विश्वसनीय tool चुनें"], ["Grant access without reviewing because extensions are always safe", "बिना समीक्षा अनुमति दें क्योंकि extensions हमेशा सुरक्षित होती हैं"], ["Upload the project to an unknown service", "Project को अज्ञात service पर upload करें"], ["Disable all project backups", "सभी project backups बंद करें"]], 0, "Extensions can run code with access to project data, so trust and least-privilege scope should be considered.", "Extensions project data तक पहुँच वाला code चला सकती हैं, इसलिए विश्वसनीयता और न्यूनतम अनुमति-सीमा पर विचार करना चाहिए।", "Expected Practice"),
        q("editors", "Hard", "A preview looks correct locally, but the uploaded page references assets from a path that exists only on the developer's computer. Which check would best catch this before release?", "Preview local रूप से सही दिखता है, लेकिन uploaded page ऐसे path से assets माँगता है जो केवल developer के computer पर है। Release से पहले कौन-सी जाँच इसे पकड़ सकती है?", [["Test the built site from a clean deployment-like directory or environment", "Built site को साफ deployment-जैसी directory या environment से जाँचें"], ["Increase editor font size", "Editor font size बढ़ाएँ"], ["Change the project icon", "Project icon बदलें"], ["Disable the browser network panel", "Browser network panel बंद करें"]], 0, "Testing the deployable output outside the developer's local paths exposes missing or incorrectly referenced assets.", "Developer के local paths से बाहर deployable output जाँचने पर अनुपस्थित या गलत संदर्भित assets सामने आते हैं।", "Expected Practice"),

        q("html", "Moderate", "A document uses headings for visual size but jumps from an h1 directly to several h4 elements. What is the better structural practice?", "दस्तावेज़ दृश्य आकार के लिए headings उपयोग करता है, लेकिन h1 के बाद सीधे कई h4 elements हैं। बेहतर संरचनात्मक तरीका क्या है?", [["Choose heading levels that reflect the content hierarchy", "ऐसे heading levels चुनें जो सामग्री का पदानुक्रम दर्शाएँ"], ["Choose heading tags only by their default font size", "Heading tags केवल उनके default font size से चुनें"], ["Replace all headings with bold text", "सभी headings को bold text से बदलें"], ["Use a heading element for every paragraph", "हर paragraph के लिए heading element उपयोग करें"]], 0, "A logical heading outline communicates relationships between sections beyond visual appearance.", "तार्किक heading outline दृश्य रूप से आगे बढ़कर sections के संबंध बताती है।", "Expected Practice"),
        q("html", "Moderate", "A link should point to another page in the same website regardless of the domain's current host name. Which URL form is generally suitable?", "Link को उसी website के दूसरे पेज पर जाना चाहिए, चाहे domain का वर्तमान host name कुछ भी हो। सामान्यतः कौन-सा URL रूप उपयुक्त है?", [["A relative path from the current document", "वर्तमान दस्तावेज़ से relative path"], ["A hard-coded path to the developer's local disk", "Developer की local disk का hard-coded path"], ["A fragment pointing to an unrelated page", "असंबंधित पेज की ओर fragment"], ["A mail address in the image source", "Image source में mail address"]], 0, "Relative URLs resolve within the site's path structure and avoid tying links to a particular hostname.", "Relative URLs site की path संरचना में resolve होते हैं और links को किसी एक hostname से बाँधते नहीं हैं।", "Expected Practice"),
        q("html", "Moderate", "A data table has column headings that should be announced when a screen reader user moves through its cells. Which markup helps identify those headings?", "Data table में ऐसे column headings हैं जो screen reader उपयोगकर्ता के cells में जाने पर घोषित होने चाहिए। कौन-सा markup headings पहचानने में मदद करता है?", [["Use header cells with appropriate scope", "उचित scope वाले header cells उपयोग करें"], ["Use bold text in ordinary data cells only", "केवल सामान्य data cells में bold text करें"], ["Set the table border to zero", "Table border शून्य रखें"], ["Place headings in a CSS background image", "Headings को CSS background image में रखें"]], 0, "Header cells and scope associate table data with the relevant row or column headings.", "Header cells और scope table data को संबंधित row या column headings से जोड़ते हैं।", "Expected Practice"),
        q("html", "Moderate", "A page embeds an audio recording that visitors should be able to start and pause. Which HTML feature provides the standard browser controls?", "एक पेज में audio recording है जिसे आगंतुक चला और रोक सकें। कौन-सी HTML सुविधा मानक browser controls देती है?", [["The audio element with controls enabled", "controls सक्रिय वाला audio element"], ["A title element around the file name", "File name के चारों ओर title element"], ["A meta element with the audio URL", "Audio URL वाला meta element"], ["A table caption containing the file size", "File size वाला table caption"]], 0, "The audio element represents playable audio, and its controls attribute exposes browser playback controls.", "Audio element चलने योग्य audio दर्शाता है और उसका controls attribute browser playback controls दिखाता है।", "Expected Practice"),
        q("html", "Moderate", "A form should prevent submission when a required email field is empty. Which native HTML attribute expresses that requirement?", "Form को खाली required email field के साथ submission रोकना चाहिए। कौन-सा native HTML attribute यह आवश्यकता बताता है?", [["required", "required"], ["download", "download"], ["colspan", "colspan"], ["autofocus only", "केवल autofocus"]], 0, "The required constraint participates in the browser's built-in form validation before submission.", "required constraint submission से पहले browser के built-in form validation में भाग लेता है।", "Expected Practice"),
        q("html", "Hard", "A table header should span the first two columns, while the following data rows remain aligned. Which attribute belongs on that header cell?", "Table header को पहले दो columns में फैलना चाहिए और नीचे की data rows aligned रहनी चाहिए। उस header cell पर कौन-सा attribute होना चाहिए?", [["colspan=\"2\"", "colspan=\"2\""], ["rowspan=\"0\"", "rowspan=\"0\""], ["target=\"_blank\"", "target=\"_blank\""], ["rel=\"stylesheet\"", "rel=\"stylesheet\""]], 0, "The colspan attribute makes one table cell occupy the specified number of columns.", "colspan attribute एक table cell को निर्धारित संख्या के columns में फैलाता है।", "Expected Practice"),
        q("html", "Hard", "A link opens a new browsing context for an external site. Which additional relationship is prudent when using target=\"_blank\"?", "एक link बाहरी site को नए browsing context में खोलता है। target=\"_blank\" उपयोग करते समय कौन-सा अतिरिक्त संबंध विवेकपूर्ण है?", [["Use rel=\"noopener\" to prevent access through window.opener", "window.opener के माध्यम से पहुँच रोकने के लिए rel=\"noopener\" उपयोग करें"], ["Use colspan to isolate the destination", "Destination अलग करने के लिए colspan उपयोग करें"], ["Use alt text on the anchor element", "Anchor element पर alt text उपयोग करें"], ["Use the required attribute on the link", "Link पर required attribute उपयोग करें"]], 0, "noopener prevents the opened page from receiving a window.opener reference to the originating page.", "noopener खोले गए पेज को मूल पेज का window.opener reference मिलने से रोकता है।", "Expected Practice"),
        q("html", "Hard", "An HTML document contains non-ASCII text, but some browsers display corrupted characters. Which head declaration should be verified?", "HTML document में non-ASCII text है, लेकिन कुछ browsers में अक्षर बिगड़े दिखते हैं। कौन-सी head declaration जाँचनी चाहिए?", [["The character encoding declaration, typically UTF-8", "Character encoding declaration, सामान्यतः UTF-8"], ["The table summary attribute", "Table summary attribute"], ["The image width attribute", "Image width attribute"], ["The form method value", "Form method value"]], 0, "Declaring the character encoding lets browsers decode the document's bytes consistently.", "Character encoding घोषित करने से browsers दस्तावेज़ के bytes को सुसंगत रूप से decode कर पाते हैं।", "Expected Practice"),

        q("css", "Moderate", "A child element should inherit the text color set on its parent. Which CSS behavior normally provides this?", "Child element को parent पर निर्धारित text color विरासत में मिलना चाहिए। कौन-सा CSS व्यवहार सामान्यतः यह देता है?", [["Inheritance of the color property", "color property का inheritance"], ["The box model's content sizing", "Box model की content sizing"], ["A media query breakpoint", "Media query breakpoint"], ["A stacking context", "Stacking context"]], 0, "Many text-related properties, including color, inherit their computed value from the parent unless overridden.", "Color सहित कई text-संबंधी properties का computed value parent से मिलता है, जब तक उसे override न किया जाए।", "Expected Practice"),
        q("css", "Moderate", "A box should keep its declared width inclusive of padding and border. Which box-sizing value makes that calculation straightforward?", "एक box की declared width में padding और border भी शामिल रहने चाहिए। कौन-सा box-sizing मान यह गणना सरल करता है?", [["border-box", "border-box"], ["content-box", "content-box"], ["inheritance: none", "inheritance: none"], ["position: fixed", "position: fixed"]], 0, "With border-box, the declared width covers content, padding and border together.", "border-box में घोषित width content, padding और border तीनों को शामिल करती है।", "Expected Practice"),
        q("css", "Moderate", "Several cards should occupy equal-width columns and wrap onto a new row when space runs out. Which CSS layout system is a natural fit?", "कई cards को समान-चौड़ाई वाले columns में रहना और जगह कम होने पर अगली row में जाना है। कौन-सा CSS layout system उपयुक्त है?", [["Flexbox with wrapping enabled", "Wrapping सक्षम वाला Flexbox"], ["A fixed background image", "Fixed background image"], ["Text decoration", "Text decoration"], ["A font-face declaration", "Font-face declaration"]], 0, "A wrapping flex container distributes items along a row and moves them to additional lines when needed.", "Wrapping वाला flex container items को row में बाँटता है और आवश्यकता पर अगली lines में भेजता है।", "Expected Practice"),
        q("css", "Moderate", "A decorative icon should appear before every element matching a selector without adding extra HTML. Which CSS mechanism can generate that content?", "बिना अतिरिक्त HTML जोड़े selector से मेल खाते हर element से पहले सजावटी icon दिखाना है। कौन-सा CSS तंत्र यह content बना सकता है?", [["The ::before pseudo-element", "::before pseudo-element"], ["The @font-face rule", "@font-face rule"], ["The z-index property", "z-index property"], ["The border-collapse property", "border-collapse property"]], 0, "The ::before pseudo-element creates generated content at the beginning of a selected element's content.", "::before pseudo-element चुने गए element की सामग्री की शुरुआत में generated content बनाता है।", "Expected Practice"),
        q("css", "Moderate", "A navigation bar should remain at the top of the viewport while the page scrolls, without leaving normal document flow initially. Which positioning value is designed for this behavior?", "Page scroll होने पर navigation bar viewport के ऊपर बनी रहनी चाहिए, लेकिन शुरुआत में normal document flow से बाहर न हो। कौन-सा positioning value इसके लिए है?", [["sticky", "sticky"], ["static", "static"], ["absolute", "absolute"], ["inherit-only", "केवल inherit"]], 0, "Sticky positioning behaves in normal flow until its scroll threshold is reached, then sticks within its scroll container.", "Sticky positioning threshold तक normal flow में रहती है, फिर अपने scroll container में चिपक जाती है।", "Expected Practice"),
        q("css", "Hard", "Two overlapping positioned elements should be layered predictably, but changing z-index has no effect. What should be investigated first?", "दो overlapping positioned elements की layer क्रमबद्ध होनी चाहिए, लेकिन z-index बदलने पर असर नहीं होता। पहले क्या जाँचना चाहिए?", [["Whether ancestor stacking contexts constrain their stacking order", "क्या ancestor stacking contexts उनका stacking order सीमित करते हैं"], ["Whether the elements use different font families", "क्या elements अलग font families उपयोग करते हैं"], ["Whether the stylesheet has a media query", "क्या stylesheet में media query है"], ["Whether the page includes a table", "क्या पेज में table है"]], 0, "Stacking contexts form independent layering groups, so a descendant cannot out-rank content in another context simply with a larger z-index.", "Stacking contexts स्वतंत्र layering groups बनाते हैं, इसलिए descendant केवल बड़ा z-index देकर दूसरे context की सामग्री से ऊपर नहीं जा सकता।", "Expected Practice"),
        q("css", "Hard", "A narrow-screen rule should apply only when the viewport is at most 600 pixels wide. Which media condition expresses that upper bound?", "Narrow-screen नियम केवल तब लागू होना चाहिए जब viewport अधिकतम 600 pixels चौड़ा हो। कौन-सी media condition यह ऊपरी सीमा बताती है?", [["@media (max-width: 600px)", "@media (max-width: 600px)"], ["@media (min-height: 600px)", "@media (min-height: 600px)"], ["@supports (color: 600px)", "@supports (color: 600px)"], ["@keyframes (width: 600px)", "@keyframes (width: 600px)"]], 0, "The max-width feature matches viewports whose width is no greater than the specified value.", "max-width feature उन viewports से मेल करता है जिनकी चौड़ाई निर्धारित मान से अधिक नहीं है।", "Expected Practice"),
        q("css", "Hard", "A component needs a shared brand color that can be updated once and reused across many rules. Which CSS feature best supports this?", "किसी component को साझा brand color चाहिए जिसे एक बार बदलकर कई rules में उपयोग किया जा सके। कौन-सी CSS सुविधा उपयुक्त है?", [["A custom property declared with -- and read with var()", " -- से घोषित और var() से पढ़ी जाने वाली custom property"], ["A repeated inline color literal on every element", "हर element पर दोहराया गया inline color literal"], ["The content property on the body", "Body पर content property"], ["A browser bookmark", "Browser bookmark"]], 0, "CSS custom properties centralize reusable values and allow them to be consumed with var().", "CSS custom properties पुनः उपयोग योग्य मानों को केंद्रित करती हैं और var() से उन्हें उपयोग करने देती हैं।", "Expected Practice"),

        q("css-frameworks", "Moderate", "A framework utility class adds a small spacing value to an element without a custom selector. What is the main benefit of this utility-first approach?", "Framework utility class बिना custom selector के element में थोड़ा spacing जोड़ती है। इस utility-first तरीके का मुख्य लाभ क्या है?", [["It applies a focused reusable style directly through a documented class", "यह दस्तावेज़ित class से केंद्रित पुनः उपयोग योग्य style सीधे लागू करती है"], ["It replaces HTML attributes with DNS settings", "यह HTML attributes को DNS settings से बदलती है"], ["It guarantees every layout is accessible automatically", "यह हर layout को अपने आप accessible होने की गारंटी देती है"], ["It stores page content on the visitor's device permanently", "यह पेज सामग्री आगंतुक के device पर स्थायी रूप से रखती है"]], 0, "Utility classes provide small composable styles that can be reused without writing a separate rule for each instance.", "Utility classes छोटी संयोज्य styles देती हैं जिन्हें हर उपयोग के लिए अलग rule लिखे बिना दोहराया जा सकता है।", "Expected Practice"),
        q("css-frameworks", "Moderate", "A framework's bundled CSS is imported into a project through its documented package entry point. Why is this preferable to copying a minified file manually?", "Framework की bundled CSS documented package entry point से project में import होती है। Minified file को हाथ से copy करने से यह बेहतर क्यों है?", [["The dependency and update process remain explicit and repeatable", "Dependency और update प्रक्रिया स्पष्ट तथा दोहराने योग्य रहती है"], ["The browser no longer needs to download CSS", "Browser को अब CSS download नहीं करनी पड़ती"], ["It disables all framework breakpoints", "यह सभी framework breakpoints बंद करता है"], ["It guarantees the HTML has no errors", "यह HTML में त्रुटि न होने की गारंटी देता है"]], 0, "A declared package dependency is easier to version, update and reproduce across environments than an undocumented manual copy.", "घोषित package dependency को undocumented manual copy की तुलना में version, update और अलग environments में दोहराना आसान है।", "Expected Practice"),
        q("css-frameworks", "Moderate", "A reusable framework button component needs the same visual style on several pages. What should the team do instead of duplicating page-specific rules?", "एक reusable framework button component को कई पेजों पर समान दृश्य शैली चाहिए। Page-specific rules दोहराने के बजाय team को क्या करना चाहिए?", [["Use the shared component class or documented component API", "Shared component class या documented component API उपयोग करें"], ["Copy the button markup into a background image", "Button markup को background image में copy करें"], ["Override unrelated selectors on each page", "हर पेज पर असंबंधित selectors override करें"], ["Move all button styles into URL parameters", "सभी button styles URL parameters में डालें"]], 0, "A shared component API keeps presentation consistent and centralizes future changes.", "Shared component API प्रस्तुति सुसंगत रखती है और भविष्य के बदलाव केंद्रित करती है।", "Expected Practice"),
        q("css-frameworks", "Moderate", "A framework's grid columns are misaligned because columns were placed directly in a container that requires a row wrapper. What is the best correction?", "Framework के grid columns गलत aligned हैं क्योंकि columns को ऐसे container में सीधे रखा गया है जिसे row wrapper चाहिए। सबसे अच्छा सुधार क्या है?", [["Wrap the columns in the framework's expected row structure", "Columns को framework की अपेक्षित row संरचना में रखें"], ["Add a second HTML doctype", "दूसरा HTML doctype जोड़ें"], ["Convert the columns to image files", "Columns को image files में बदलें"], ["Change the site's DNS records", "Site के DNS records बदलें"]], 0, "Framework grid systems commonly depend on a container-row-column hierarchy for gutters and alignment.", "Framework grid systems में gutters और alignment के लिए container-row-column पदानुक्रम सामान्यतः आवश्यक होता है।", "Expected Practice"),
        q("css-frameworks", "Moderate", "A project includes only a small set of framework components. What benefit can importing only the needed modules provide?", "एक project में framework के केवल कुछ components चाहिए। केवल आवश्यक modules import करने से क्या लाभ हो सकता है?", [["A smaller delivered stylesheet and fewer unused rules", "छोटी delivered stylesheet और कम अप्रयुक्त rules"], ["Automatic translation of every page", "हर पेज का स्वचालित अनुवाद"], ["Guaranteed removal of all network latency", "सभी network latency हटने की गारंटी"], ["Automatic conversion of HTML into a database", "HTML का database में स्वचालित रूपांतरण"]], 0, "Selective imports can avoid shipping framework styles that the application never uses.", "चयनित imports उन framework styles को भेजने से बचा सकते हैं जिनका application उपयोग नहीं करता।", "Expected Practice"),
        q("css-frameworks", "Hard", "Two framework components use identical generic class names, and a local rule unexpectedly affects both. Which customization strategy limits the side effect?", "दो framework components समान generic class names उपयोग करते हैं और एक local rule अनपेक्षित रूप से दोनों को प्रभावित करता है। कौन-सी customization रणनीति side effect सीमित करती है?", [["Scope the override beneath a component-specific class", "Override को component-specific class के भीतर सीमित करें"], ["Use a universal selector for every element", "हर element के लिए universal selector उपयोग करें"], ["Append !important to every declaration", "हर declaration में !important जोड़ें"], ["Put styles in an HTML comment", "Styles को HTML comment में रखें"]], 0, "A component-scoped selector reduces unintended matches elsewhere in the application.", "Component-scoped selector application के अन्य हिस्सों में अनचाहे matches घटाता है।", "Expected Practice"),
        q("css-frameworks", "Hard", "A framework update changes a component's markup contract. How should a team reduce future upgrade surprises?", "Framework update किसी component का markup contract बदल देता है। Team भविष्य के upgrade surprises कैसे घटा सकती है?", [["Pin and review versions, then test components against documented migration guidance", "Version pin और review करें, फिर documented migration guidance के अनुसार components जाँचें"], ["Always load the newest files without testing", "बिना जाँच हमेशा नवीनतम files load करें"], ["Copy generated output into every page", "Generated output हर पेज में copy करें"], ["Delete the lockfile and ignore changes", "Lockfile हटाकर बदलाव अनदेखे करें"]], 0, "Controlled version updates and migration checks expose breaking changes before they affect the deployed site.", "नियंत्रित version updates और migration जाँच deployed site प्रभावित होने से पहले breaking changes सामने लाती हैं।", "Expected Practice"),
        q("css-frameworks", "Hard", "A grid is usable at desktop width but overflows on small screens because every column is forced to retain its desktop width. Which framework strategy addresses the root cause?", "Desktop width पर grid ठीक है, लेकिन हर column को desktop width बनाए रखने के कारण छोटी screen पर overflow होता है। कौन-सी framework रणनीति मूल कारण दूर करती है?", [["Use responsive column classes that change sizing at suitable breakpoints", "उपयुक्त breakpoints पर sizing बदलने वाली responsive column classes उपयोग करें"], ["Increase the desktop container width further", "Desktop container की width और बढ़ाएँ"], ["Set every column to a fixed pixel width", "हर column को fixed pixel width दें"], ["Hide the browser's horizontal scrollbar", "Browser का horizontal scrollbar छिपाएँ"]], 0, "Responsive column rules allow the layout to adapt instead of preserving a wide-screen sizing constraint.", "Responsive column rules चौड़ी screen की sizing सीमा बनाए रखने के बजाय layout को अनुकूलित होने देती हैं।", "Expected Practice"),

        q("javascript", "Moderate", "A counter changes a variable's value inside a block, but the value should not be reassigned later. Which declaration communicates that intent?", "एक counter block के भीतर variable का मान बदलता है, लेकिन बाद में उसे फिर assign नहीं करना चाहिए। कौन-सी declaration यह आशय बताती है?", [["Use let for the changing counter and const for values that are not reassigned", "बदलते counter के लिए let और दोबारा assign न होने वाले मानों के लिए const उपयोग करें"], ["Declare every variable with var and avoid blocks", "हर variable को var से घोषित करें और blocks से बचें"], ["Use a CSS custom property as a JavaScript variable", "JavaScript variable के रूप में CSS custom property उपयोग करें"], ["Use an HTML id as the declaration", "Declaration के रूप में HTML id उपयोग करें"]], 0, "let supports reassignment in its block scope, while const prevents rebinding and documents stable references.", "let अपने block scope में reassignment देता है, जबकि const rebinding रोकता है और स्थिर reference का संकेत देता है।", "Expected Practice"),
        q("javascript", "Moderate", "A form handler should stop the browser's default page navigation after submission so JavaScript can process the data. Which event method is appropriate?", "Form handler को submission के बाद browser का default page navigation रोकना है ताकि JavaScript data संसाधित करे। कौन-सा event method उपयुक्त है?", [["event.preventDefault()", "event.preventDefault()"], ["event.stopImmediatePropagation() in every case", "हर स्थिति में event.stopImmediatePropagation()"], ["window.close()", "window.close()"], ["document.write()", "document.write()"]], 0, "preventDefault cancels the event's default action while allowing the handler to continue processing.", "preventDefault event की default क्रिया रोकता है, जबकि handler को processing जारी रखने देता है।", "Expected Practice"),
        q("javascript", "Moderate", "Many list items are added and removed dynamically, and each item needs the same click behavior. Which pattern avoids attaching a new listener to every item?", "कई list items गतिशील रूप से जोड़े और हटाए जाते हैं तथा हर item का click behavior समान है। हर item पर listener जोड़ने से बचने वाला तरीका कौन-सा है?", [["Delegate the click from a stable parent and inspect the event target", "स्थिर parent से click delegate करके event target जाँचें"], ["Poll every item continuously with a timer", "Timer से हर item को लगातार poll करें"], ["Add an inline script to every text node", "हर text node में inline script जोड़ें"], ["Reload the page after every click", "हर click के बाद पेज reload करें"]], 0, "Event delegation lets a stable ancestor handle bubbled events from current or future descendants.", "Event delegation स्थिर ancestor को वर्तमान या भविष्य के descendants से bubbled events संभालने देता है।", "Expected Practice"),
        q("javascript", "Moderate", "A loop should execute once for each value in an array without manually managing an index. Which JavaScript construct is suitable?", "Array के हर मान के लिए loop चलना चाहिए और index को हाथ से संभालना नहीं है। कौन-सा JavaScript construct उपयुक्त है?", [["for...of", "for...of"], ["switch...case", "switch...case"], ["try...catch", "try...catch"], ["with...style", "with...style"]], 0, "for...of iterates over the values of an iterable such as an array.", "for...of array जैसे iterable के मानों पर iteration करता है।", "Expected Practice"),
        q("javascript", "Moderate", "In AngularJS, a view should display a model value and update when that model changes. Which core concept provides this synchronization?", "AngularJS view को model value दिखानी है और model बदलने पर अपडेट होना है। कौन-सी मुख्य अवधारणा यह synchronization देती है?", [["Data binding", "Data binding"], ["DNS delegation", "DNS delegation"], ["CSS inheritance alone", "केवल CSS inheritance"], ["Image masking", "Image masking"]], 0, "AngularJS data binding connects model data and view expressions so changes can be reflected in the interface.", "AngularJS data binding model data और view expressions को जोड़ती है ताकि बदलाव interface में दिखें।", "Expected Practice"),
        q("javascript", "Hard", "A page has 500 buttons created from the same template. Each button has an identical handler, but attaching a listener to every button is costly. Which approach is most efficient and maintainable?", "एक पेज में समान template से बने 500 buttons हैं। हर button का handler समान है, लेकिन सभी पर listener जोड़ना महँगा है। कौन-सा तरीका कुशल और maintainable है?", [["Attach one delegated listener to a stable ancestor and match the button target", "स्थिर ancestor पर एक delegated listener लगाएँ और button target पहचानें"], ["Create a separate timer for each button", "हर button के लिए अलग timer बनाएँ"], ["Copy the handler source into each button's text", "Handler source हर button के text में copy करें"], ["Attach a listener only to the document title", "केवल document title पर listener लगाएँ"]], 0, "One delegated listener handles bubbling events from many descendants and also works for dynamically inserted buttons.", "एक delegated listener कई descendants के bubbling events संभालता है और बाद में जोड़े गए buttons पर भी काम करता है।", "Expected Practice"),
        q("javascript", "Hard", "An AngularJS page repeats a list, but each rendered row should keep a stable identity when items are reordered. Which approach helps AngularJS track those rows?", "AngularJS पेज list दोहराता है, लेकिन items का क्रम बदलने पर हर rendered row की स्थिर पहचान रहनी चाहिए। AngularJS को rows track करने में क्या मदद करता है?", [["Use a unique item key with track by in the repeat expression", "Repeat expression में track by के साथ unique item key उपयोग करें"], ["Use the array's display text as a CSS color", "Array के display text को CSS color की तरह उपयोग करें"], ["Disable the digest cycle", "Digest cycle बंद करें"], ["Replace the list with a single screenshot", "List को एक screenshot से बदलें"]], 0, "A stable track-by key lets AngularJS associate rendered DOM rows with their underlying items across reordering.", "स्थिर track-by key AngularJS को क्रम बदलने पर rendered DOM rows को उनके मूल items से जोड़ने देती है।", "Expected Practice"),
        q("javascript", "Hard", "A JavaScript function is passed to another function to run after an asynchronous request completes. What is that passed function commonly called?", "Asynchronous request पूरी होने पर चलाने के लिए एक JavaScript function दूसरे function को दिया जाता है। उस दिए गए function को सामान्यतः क्या कहते हैं?", [["A callback", "Callback"], ["A selector", "Selector"], ["A stylesheet", "Stylesheet"], ["A constructor attribute", "Constructor attribute"]], 0, "A callback is a function supplied to another operation so it can be invoked at an appropriate later point.", "Callback वह function है जो किसी दूसरी क्रिया को दिया जाता है ताकि उपयुक्त बाद के समय पर उसे चलाया जा सके।", "Expected Practice"),

        q("image-editing", "Moderate", "An editor wants a warmer look but may need to revise the color change later. Which workflow is most editable?", "Editor को अधिक warm रूप चाहिए, लेकिन बाद में color बदलाव संशोधित करना पड़ सकता है। कौन-सा workflow अधिक editable है?", [["Apply a separate adjustment layer", "अलग adjustment layer लागू करें"], ["Permanently flatten and overwrite the source", "स्थायी रूप से flatten करके source overwrite करें"], ["Erase the blue channel from the original pixels", "Original pixels से blue channel मिटाएँ"], ["Export immediately to a low-quality JPEG only", "तुरंत केवल low-quality JPEG export करें"]], 0, "An adjustment layer keeps the tonal or color change separate from the original image pixels.", "Adjustment layer tonal या color बदलाव को original image pixels से अलग रखती है।", "Expected Practice"),
        q("image-editing", "Moderate", "A portrait has a small sensor spot that should be replaced with nearby texture while blending into the surrounding area. Which retouching tool is designed for this?", "Portrait में छोटा sensor spot है जिसे पास की texture से बदलकर आसपास में blend करना है। कौन-सा retouching tool इसके लिए बनाया गया है?", [["Healing tool", "Healing tool"], ["Gradient tool", "Gradient tool"], ["Text tool", "Text tool"], ["Crop tool", "Crop tool"]], 0, "Healing tools sample nearby pixels and blend the correction with surrounding tones and texture.", "Healing tools पास के pixels लेकर सुधार को आसपास के tones और texture के साथ blend करते हैं।", "Expected Practice"),
        q("image-editing", "Moderate", "A square photograph must fit a wide banner while keeping the subject centered. Which operation changes the visible framing without stretching the subject?", "चौकोर photograph को subject केंद्र में रखते हुए चौड़े banner में फिट करना है। Subject को खींचे बिना दृश्य framing कौन-सी क्रिया बदलेगी?", [["Crop the image to the banner's aspect ratio", "Image को banner के aspect ratio में crop करें"], ["Increase horizontal scale only", "केवल horizontal scale बढ़ाएँ"], ["Change the file extension to SVG", "File extension को SVG में बदलें"], ["Apply a sharpen filter repeatedly", "Sharpen filter बार-बार लगाएँ"]], 0, "Cropping selects a new composition and aspect ratio without distorting the proportions of the retained content.", "Cropping नई composition और aspect ratio चुनती है, बिना रखी गई सामग्री के अनुपात बिगाड़े।", "Expected Practice"),
        q("image-editing", "Moderate", "A web graphic needs transparent areas around its subject. Which common raster format supports an alpha channel for that use?", "एक web graphic में subject के चारों ओर transparent क्षेत्र चाहिए। कौन-सा सामान्य raster format इसके लिए alpha channel समर्थित करता है?", [["PNG", "PNG"], ["JPEG", "JPEG"], ["BMP without transparency", "Transparency के बिना BMP"], ["Plain text", "Plain text"]], 0, "PNG supports alpha transparency, whereas standard JPEG does not preserve transparent pixels.", "PNG alpha transparency समर्थित करता है, जबकि सामान्य JPEG transparent pixels सुरक्षित नहीं रखता।", "Expected Practice"),
        q("image-editing", "Moderate", "A photo looks too dark in the midtones, but highlights should remain controlled. Which adjustment is most appropriate to evaluate?", "Photo के midtones बहुत dark हैं, लेकिन highlights नियंत्रित रहने चाहिए। किस adjustment पर विचार करना सबसे उपयुक्त है?", [["A levels or curves adjustment focused on tonal range", "Tonal range पर केंद्रित levels या curves adjustment"], ["A canvas rotation", "Canvas rotation"], ["A layer rename", "Layer rename"], ["A vector path stroke", "Vector path stroke"]], 0, "Levels and curves adjust tonal values and allow midtones to be changed while monitoring highlights and shadows.", "Levels और curves tonal values बदलते हैं और highlights तथा shadows देखते हुए midtones समायोजित करने देते हैं।", "Expected Practice"),
        q("image-editing", "Hard", "An editor must move an object independently while preserving the ability to reposition it relative to the background. How should the object be prepared?", "Editor को object को स्वतंत्र रूप से स्थानांतरित करना है और background के सापेक्ष फिर reposition करने की क्षमता रखनी है। Object कैसे तैयार करें?", [["Select the object onto a separate layer with a transparent background", "Object को transparent background वाली अलग layer पर select करें"], ["Flatten the object and background before moving", "स्थानांतरित करने से पहले object और background flatten करें"], ["Paint over the background on the only layer", "एकमात्र layer पर background के ऊपर paint करें"], ["Convert the whole image to a single-color bitmap", "पूरी image को single-color bitmap में बदलें"]], 0, "A separate layer isolates the object and preserves independent positioning and editing.", "अलग layer object को अलग करती है और स्वतंत्र positioning तथा editing बचाती है।", "Expected Practice"),
        q("image-editing", "Hard", "A photograph contains a smooth gradient, but saving it as a low-color indexed image creates visible bands. Which export choice best reduces this artifact?", "Photograph में smooth gradient है, लेकिन low-color indexed image के रूप में save करने पर bands दिखते हैं। कौन-सा export विकल्प यह artifact घटाता है?", [["Use a true-color format with sufficient color depth", "पर्याप्त color depth वाला true-color format उपयोग करें"], ["Reduce the palette to fewer colors", "Palette में रंग और घटाएँ"], ["Convert the gradient to plain text", "Gradient को plain text में बदलें"], ["Increase the image's cropping amount", "Image का cropping अधिक करें"]], 0, "A format with sufficient color depth can represent gradual tonal changes more smoothly than a restricted palette.", "पर्याप्त color depth वाला format सीमित palette की तुलना में धीरे बदलते tones अधिक smooth दिखा सकता है।", "Expected Practice"),
        q("image-editing", "Hard", "A retoucher needs to remove a cable, but nearby texture varies along its length. Why might a clone tool be preferable to a healing tool in some sections?", "Retoucher को cable हटानी है, लेकिन उसके साथ की texture अलग-अलग है। कुछ हिस्सों में healing tool के बजाय clone tool क्यों बेहतर हो सकता है?", [["It copies sampled pixels more directly when precise texture placement is needed", "सटीक texture placement चाहिए तो यह sampled pixels अधिक सीधे copy करता है"], ["It automatically creates vector paths", "यह अपने आप vector paths बनाता है"], ["It preserves a transparent alpha channel by definition", "यह परिभाषा से transparent alpha channel सुरक्षित रखता है"], ["It changes the document's print resolution", "यह दस्तावेज़ का print resolution बदलता है"]], 0, "Cloning gives direct control over sampled source pixels, which can help when automatic blending would alter important texture.", "Cloning sampled source pixels पर सीधा नियंत्रण देता है, जो automatic blending से महत्वपूर्ण texture बदलने की स्थिति में उपयोगी है।", "Expected Practice"),

        q("web-publishing", "Moderate", "A domain should point to a specific IPv4 address for the website host. Which DNS record type is commonly used?", "Domain को website host के एक निश्चित IPv4 address की ओर इंगित करना है। सामान्यतः कौन-सा DNS record type उपयोग होता है?", [["A record", "A record"], ["CNAME record only", "केवल CNAME record"], ["MX record", "MX record"], ["PTR record for mail delivery", "Mail delivery के लिए PTR record"]], 0, "An A record maps a hostname to an IPv4 address.", "A record hostname को IPv4 address से map करता है।", "Expected Practice"),
        q("web-publishing", "Moderate", "A site has deployed its files, but requesting the domain root should automatically show the site's home page. Which server configuration is commonly involved?", "Site की files deploy हो गई हैं, लेकिन domain root खोलने पर home page अपने आप दिखना चाहिए। सामान्यतः कौन-सा server configuration इसमें शामिल है?", [["Set the correct default index document", "सही default index document निर्धारित करें"], ["Change the image's color profile", "Image का color profile बदलें"], ["Set a mail exchanger record", "Mail exchanger record निर्धारित करें"], ["Add a CSS hover selector", "CSS hover selector जोड़ें"]], 0, "The host's default-document setting determines which file is served when a directory is requested.", "Host की default-document setting तय करती है कि directory माँगने पर कौन-सी file दी जाएगी।", "Expected Practice"),
        q("web-publishing", "Moderate", "A maintainer needs to upload website files over an encrypted connection to a hosting account. Which transfer option is preferable to plain FTP?", "Maintainer को hosting account पर encrypted connection से website files upload करनी हैं। Plain FTP की तुलना में कौन-सा transfer विकल्प बेहतर है?", [["SFTP over SSH", "SSH पर SFTP"], ["Unencrypted FTP with a public password", "Public password वाला unencrypted FTP"], ["An HTTP image request", "HTTP image request"], ["A DNS lookup", "DNS lookup"]], 0, "SFTP encrypts the file-transfer session over SSH, protecting credentials and transferred data in transit.", "SFTP, SSH के माध्यम से file-transfer session encrypt करता है और credentials तथा data को transit में सुरक्षित रखता है।", "Expected Practice"),
        q("web-publishing", "Moderate", "A website moves to a new hosting server while keeping its existing domain name. Which record's destination commonly needs updating?", "Website नया hosting server उपयोग करने लगती है, लेकिन domain name वही रहता है। सामान्यतः किस record का destination बदलना पड़ता है?", [["The domain's address record to the new host", "नए host की ओर domain का address record"], ["The HTML lang attribute", "HTML lang attribute"], ["The browser's bookmark title", "Browser bookmark title"], ["The image's alt text", "Image का alt text"]], 0, "DNS address records direct the hostname to a server, so their destination must match the new host when applicable.", "DNS address records hostname को server तक पहुँचाते हैं, इसलिए आवश्यकता पर उनका destination नए host से मेल खाना चाहिए।", "Expected Practice"),
        q("web-publishing", "Moderate", "A website owner wants search engines to discover the site's important URLs more easily. Which file can list those URLs for crawlers?", "Website owner चाहता है कि search engines महत्वपूर्ण URLs आसानी से खोजें। Crawlers के लिए कौन-सी file वे URLs सूचीबद्ध कर सकती है?", [["An XML sitemap", "XML sitemap"], ["A CSS sprite", "CSS sprite"], ["A browser cache file", "Browser cache file"], ["A font stylesheet", "Font stylesheet"]], 0, "An XML sitemap communicates canonical URLs that a site owner wants search engines to know about.", "XML sitemap उन canonical URLs की जानकारी देती है जिनके बारे में site owner search engines को बताना चाहता है।", "Expected Practice"),
        q("web-publishing", "Hard", "A page has permanently moved to a new URL, and old links should transfer users and search signals to the replacement. Which response is most appropriate?", "एक पेज स्थायी रूप से नए URL पर चला गया है और पुराने links से users तथा search signals नए पेज तक पहुँचने चाहिए। कौन-सा response उपयुक्त है?", [["A permanent 301 redirect to the replacement URL", "Replacement URL पर permanent 301 redirect"], ["A temporary client-side alert only", "केवल temporary client-side alert"], ["A 404 response with no explanation", "बिना स्पष्टीकरण 404 response"], ["A DNS MX record", "DNS MX record"]], 0, "A permanent redirect communicates that the resource has moved and directs clients to its new location.", "Permanent redirect बताता है कि resource स्थानांतरित हो गया है और clients को नए स्थान पर भेजता है।", "Expected Practice"),
        q("web-publishing", "Hard", "A page uses a valid HTTPS certificate today, but the certificate will expire soon. Which maintenance practice prevents avoidable browser trust warnings?", "आज पेज पर वैध HTTPS certificate है, लेकिन वह जल्द समाप्त होगा। कौन-सी maintenance practice अनावश्यक browser trust warnings रोकती है?", [["Monitor certificate expiry and renew or automate renewal before expiration", "Certificate expiry देखें और समाप्ति से पहले renew करें या renewal स्वचालित करें"], ["Change the website's file extensions", "Website की file extensions बदलें"], ["Disable HTTPS for all visitors", "सभी आगंतुकों के लिए HTTPS बंद करें"], ["Replace the certificate with a screenshot", "Certificate को screenshot से बदलें"]], 0, "Timely renewal maintains a trusted certificate chain and avoids expiration errors for visitors.", "समय पर renewal trusted certificate chain बनाए रखता है और आगंतुकों को expiration errors से बचाता है।", "Expected Practice"),
        q("web-publishing", "Hard", "A public site should discourage search engines from indexing a staging environment while still allowing the team to test it. Which approach is most reliable?", "एक public site staging environment को search engines द्वारा index होने से रोकना चाहती है, लेकिन team को उसे test करना है। सबसे विश्वसनीय तरीका कौन-सा है?", [["Restrict staging access with authentication or network controls", "Staging access को authentication या network controls से सीमित करें"], ["Rely only on an unlinked URL", "केवल unlinked URL पर निर्भर रहें"], ["Rename all HTML files to images", "सभी HTML files का नाम images रखें"], ["Remove the HTTPS certificate", "HTTPS certificate हटा दें"]], 0, "Access controls prevent public crawling more reliably than merely making a URL hard to discover.", "Access controls केवल URL छिपाने की तुलना में public crawling को अधिक विश्वसनीय ढंग से रोकते हैं।", "Expected Practice")
    ];
}(window));
